// Clonado do Make. Abas lidas pelo n8n e convertidas para linhas na ordem de colunas do Make.
const HEAD = {"Afiliados": ["email", "ref", "titular", "whatsapp", "pix", "status", "cadastrado_em", "atualizado_em", "codigo", "codigo_expira", "tentativas", "sessao", "sessao_expira", "desativado_em"], "Comissoes": ["payment_id", "lote", "ref", "email_afiliado", "id_netliss", "cpf", "valor_venda", "comissao", "lucro", "data_venda", "gerado_em"], "Lotes": ["lote", "ref", "email", "titular", "pix", "whatsapp", "referencia", "vendas", "valor", "status", "gerado_em", "pago_em"]};
const objs = n => $('Ler ' + n).all().map(i => i.json).filter(r => r && r.row_number);
const aba = n => [HEAD[n]].concat(objs(n).map(r => HEAD[n].map(h => r[h] == null ? '' : String(r[h]))));
const ENT = (() => { let e = null; try { e = $('Entrada').first(0); } catch (x) {} if (!e) { try { e = $('Entrada').first(1); } catch (x) {} } const w = (e && e.json) || {}; return Object.assign({}, w.query || {}, (typeof w.body === 'object' && w.body) || {}); })();
const input = Object.assign({}, ENT, { abas: ['Afiliados', 'Comissoes', 'Lotes'].map(aba) });
// Netliss - Afiliados (rotas do widget)
// Recebe a acao do widget + as abas Afiliados, Comissoes e Lotes ja lidas pelo Make.
// Devolve: resposta (vai para o widget), escrita (o Make grava na planilha), email e telegram.
const NL = String.fromCharCode(10);
const SITE = 'https://netliss.com/';
const SEGURO = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const agora = Date.now();
const out = { resposta: { ok: false }, escrita: null, email: null, telegram: null };

function txt(v) { return String(v == null ? '' : v).trim(); }
function lerJson(v) { if (v && typeof v === 'object') { return v; } try { return JSON.parse(String(v || 'null')); } catch (e) { return null; } }
function linhas(bloco) { const b = lerJson(bloco); if (!b) { return []; } const v = Array.isArray(b) ? b : (b.values || []); return v.slice(1); }
// o Math.random do Make se repete entre execucoes: usa o gerador criptografico
let CRIPTO = null;
CRIPTO = null; // no n8n usa o gerador seguro do proprio Node (globalThis.crypto)
function sorteio(n) {
  const b = [];
  if (CRIPTO && CRIPTO.randomBytes) { const r = CRIPTO.randomBytes(n); for (let i = 0; i < n; i++) { b.push(r[i]); } return b; }
  if (globalThis.crypto && globalThis.crypto.getRandomValues) { const r = new Uint8Array(n); globalThis.crypto.getRandomValues(r); for (let i = 0; i < n; i++) { b.push(r[i]); } return b; }
  throw new Error('sem gerador seguro');
}
function gera(n) { const b = sorteio(n); let s = ''; for (let i = 0; i < n; i++) { s += SEGURO.charAt(b[i] % SEGURO.length); } return s; }
function dataSP(ms) {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) { p[x.type] = x.value; }
  return p.day + '/' + p.month + '/' + p.year + ' ' + p.hour + ':' + p.minute;
}
function esc(s) { return txt(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function reais(n) { return 'R$ ' + (Math.round(Number(n || 0) * 100) / 100).toFixed(2).replace('.', ','); }
function num(v) { const s = txt(v).replace('R$', '').trim(); if (!s) { return 0; } const t = s.indexOf(',') > -1 ? s.split('.').join('').replace(',', '.') : s; const n = Number(t); return isNaN(n) ? 0 : n; }
function linkDe(ref) { return SITE + '?ref=' + ref; }
function qrDe(ref) { return 'https://api.qrserver.com/v1/create-qr-code/?size=600x600&margin=16&data=' + encodeURIComponent(linkDe(ref)); }

function moldura(chapeu, titulo, corpo) {
  return "<div style='font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #111'>" +
    "<div style='background:#0A0A0A;padding:16px 20px;text-align:center'><img src='https://i.imgur.com/9WE3IIp.png' alt='Netliss.com' width='190' style='max-width:190px;width:55%;height:auto;display:block;margin:0 auto'></div>" +
    "<div style='background:#C3F53C;height:4px'></div>" +
    "<div style='padding:28px 24px;color:#1a1a1a;line-height:1.62'>" +
    "<div style='color:#6b7a55;font-size:11px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px'>" + chapeu + "</div>" +
    "<h2 style='margin:0 0 14px;font-size:21px;color:#0A0A0A'>" + titulo + "</h2>" + corpo + "</div></div>" +
    "<div style='max-width:600px;margin:10px auto 0;text-align:center;color:#888;font-size:11px;font-family:Arial,sans-serif'>netliss.com &middot; Programa de Afiliados Netliss</div>";
}
function caixa(html) { return "<div style='background:#0A0A0A;border:1px solid #C3F53C;border-radius:10px;padding:18px;margin:0 0 20px;color:#ffffff;font-size:15px;line-height:1.65'>" + html + "</div>"; }
function primeiro(nome) { return esc(txt(nome).split(' ')[0]); }

// ---- entradas ----
const acao = txt(input.acao);
const email = txt(input.email).toLowerCase().replace(/[^a-z0-9@._+-]/g, '');
const abas = lerJson(input.abas) || [];
const lista = linhas(input.afiliados || abas[0]);
const comissoes = linhas(input.comissoes || abas[1]);
const lotes = linhas(input.lotes || abas[2]);
// colunas Afiliados: 0 email 1 ref 2 titular 3 whatsapp 4 pix 5 status 6 cadastrado_em 7 atualizado_em 8 codigo 9 codigo_expira 10 tentativas 11 sessao 12 sessao_expira 13 desativado_em
let pos = -1;
for (let i = 0; i < lista.length; i++) { if (txt(lista[i][0]).toLowerCase() === email && email) { pos = i; break; } }
const linha = pos > -1 ? lista[pos].slice(0, 14) : null;
if (linha) { while (linha.length < 14) { linha.push(''); } }
const numLinha = pos + 2; // cabecalho e a linha 1

function grava(valores) { out.escrita = { metodo: 'PUT', range: 'Afiliados!A' + numLinha + ':N' + numLinha, values: [valores] }; out.linha_obj = Object.assign({ row_number: objs('Afiliados')[pos].row_number }, Object.fromEntries(HEAD.Afiliados.map((h, i) => [h, valores[i] == null ? '' : String(valores[i])]))); }
function dados(l) { return { email: l[0], ref: l[1], titular: l[2], whatsapp: l[3], pix: l[4], status: l[5] || 'ativo', link: linkDe(l[1]), qr: qrDe(l[1]), cadastrado_em: l[6] }; }
function sessaoOk() {
  if (!linha) { return false; }
  const s = txt(input.sessao);
  return s.length >= 20 && s === txt(linha[11]) && Number(linha[12] || 0) > agora;
}
function validaZap(z) { const d = txt(z).replace(/[^0-9]/g, ''); return (d.length >= 10 && d.length <= 13) ? d : ''; }
function validaEmail(e) { return /^[^@ ]+@[^@ ]+[.][^@ ]+$/.test(e) ? e : ''; }

if (acao === 'af_cadastrar') {
  const e = validaEmail(email);
  const zap = validaZap(input.whatsapp);
  const titular = txt(input.titular).replace(/^[=+@-]+/, '').slice(0, 80);
  const pix = txt(input.pix).replace(/^[=+@]+/, '').slice(0, 120);
  if (!e || !zap || titular.length < 5 || pix.length < 4 || txt(input.aceite) !== '1') {
    out.resposta = { ok: false, motivo: 'dados' };
  } else if (linha) {
    out.resposta = { ok: false, existe: (txt(linha[5]) === 'desativado' ? 'desativado' : 'ativo') };
  } else {
    const usados = {}; for (const l of lista) { usados[txt(l[1])] = 1; }
    let ref = gera(6); let volta = 0;
    while (usados[ref] && volta < 50) { ref = gera(6); volta++; }
    const quando = dataSP(agora);
    out.escrita = { metodo: 'APPEND', range: 'Afiliados!A1:N1', values: [[e, ref, titular, zap, pix, 'ativo', quando, quando, '', '', '0', '', '', '']] }; out.linha_obj = Object.fromEntries(HEAD.Afiliados.map((h, i) => [h, out.escrita.values[0][i]]));
    out.resposta = { ok: true, ref: ref, link: linkDe(ref), qr: qrDe(ref) };
    out.email = {
      para: e, assunto: 'Bem-vindo(a) ao Programa de Afiliados Netliss',
      html: moldura('Programa de Afiliados', 'Olá, ' + primeiro(titular) + '! Seja bem-vindo(a)!',
        "<p style='margin:0 0 16px'>O seu cadastro de afiliado foi concluído. A partir de agora, todo cliente novo que contratar a Netliss pelo seu link ou QR code gera <b>20% de comissão</b> sobre o primeiro pagamento, pago via Pix no dia seguinte à venda.</p>" +
        caixa("<b style='color:#C3F53C'>Seu link:</b><br><a href='" + linkDe(ref) + "' style='color:#ffffff;word-break:break-all'>" + linkDe(ref) + "</a><br><br><b style='color:#C3F53C'>Seu código:</b> " + ref) +
        "<p style='margin:0 0 10px;text-align:center'><b>Seu QR code</b></p>" +
        "<p style='margin:0 0 18px;text-align:center'><img src='" + qrDe(ref) + "' alt='QR code' width='220' style='width:220px;height:220px;border:8px solid #ffffff;box-shadow:0 0 0 1px #ddd'></p>" +
        "<p style='margin:0 0 18px;text-align:center'><a href='" + qrDe(ref) + "' style='color:#0A0A0A'>Abrir o QR code em tamanho grande</a></p>" +
        "<p style='margin:0 0 8px;color:#333'>Para ver seus dados, resultados ou pegar o link de novo, entre no chat do site em <b>Ganhe dinheiro indicando a Netliss</b> e depois em <b>Já sou afiliado</b>.</p>")
    };
    out.telegram = '🤝 NOVO AFILIADO' + NL + titular + NL + 'E-mail: ' + e + NL + 'WhatsApp: ' + zap + NL + 'Pix: ' + pix + NL + 'Código: ' + ref;
  }
} else if (acao === 'af_codigo') {
  if (!linha) {
    out.resposta = { ok: false, existe: false };
  } else if (Number(linha[9] || 0) - agora > 540000) {
    out.resposta = { ok: false, motivo: 'espere' };
  } else {
    const cod = gera(6);
    linha[8] = cod; linha[9] = String(agora + 600000); linha[10] = '0';
    grava(linha);
    out.resposta = { ok: true, status: txt(linha[5]) === 'desativado' ? 'desativado' : 'ativo' };
    out.email = {
      para: linha[0], assunto: 'Seu código de acesso de afiliado: ' + cod,
      html: moldura('Acesso de afiliado', 'Olá, ' + primeiro(linha[2]) + '!',
        "<p style='margin:0 0 16px'>Use o código abaixo no chat da Netliss para entrar na sua área de afiliado:</p>" +
        caixa("<div style='text-align:center;font-size:30px;letter-spacing:8px;font-weight:bold;color:#C3F53C'>" + cod + "</div>") +
        "<p style='margin:0;color:#555;font-size:13px'>O código vale por 10 minutos. Se não foi você quem pediu, é só ignorar este e-mail.</p>")
    };
  }
} else if (acao === 'af_entrar') {
  const cod = txt(input.codigo).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!linha || !txt(linha[8])) {
    out.resposta = { ok: false, motivo: 'expirado' };
  } else if (Number(linha[9] || 0) < agora) {
    out.resposta = { ok: false, motivo: 'expirado' };
  } else if (Number(linha[10] || 0) >= 3) {
    out.resposta = { ok: false, motivo: 'bloqueado' };
  } else if (cod !== txt(linha[8])) {
    const t = Number(linha[10] || 0) + 1;
    linha[10] = String(t);
    if (t >= 3) { linha[8] = ''; linha[9] = ''; }
    grava(linha);
    out.resposta = { ok: false, motivo: t >= 3 ? 'bloqueado' : 'errado', restam: Math.max(0, 3 - t) };
  } else {
    const ses = gera(28);
    linha[8] = ''; linha[9] = ''; linha[10] = '0'; linha[11] = ses; linha[12] = String(agora + 7200000);
    grava(linha);
    out.resposta = { ok: true, sessao: ses, dados: dados(linha) };
  }
} else if (['af_dados', 'af_editar', 'af_excluir', 'af_reativar', 'af_resultados'].indexOf(acao) > -1) {
  if (!sessaoOk()) {
    out.resposta = { ok: false, motivo: 'sessao' };
  } else if (acao === 'af_dados') {
    out.resposta = { ok: true, dados: dados(linha) };
  } else if (acao === 'af_editar') {
    const campo = txt(input.campo);
    let mudou = '';
    if (campo === 'whatsapp') {
      const z = validaZap(input.whatsapp);
      if (z) { mudou = 'WhatsApp: ' + linha[3] + ' → ' + z; linha[3] = z; }
    } else if (campo === 'pix') {
      const p = txt(input.pix).replace(/^[=+@]+/, '').slice(0, 120);
      const t = txt(input.titular).replace(/^[=+@-]+/, '').slice(0, 80);
      if (p.length >= 4 && t.length >= 5) { mudou = 'Pix: ' + linha[4] + ' → ' + p + NL + 'Titular: ' + linha[2] + ' → ' + t; linha[4] = p; linha[2] = t; }
    }
    if (!mudou) {
      out.resposta = { ok: false, motivo: 'dados' };
    } else {
      linha[7] = dataSP(agora);
      grava(linha);
      out.resposta = { ok: true, dados: dados(linha) };
      out.telegram = '✏️ AFILIADO ALTEROU DADOS' + NL + linha[2] + ' (' + linha[1] + ')' + NL + mudou;
    }
  } else if (acao === 'af_excluir') {
    linha[5] = 'desativado'; linha[13] = dataSP(agora); linha[7] = linha[13]; linha[11] = ''; linha[12] = '';
    grava(linha);
    out.resposta = { ok: true };
    out.telegram = '🚫 AFILIADO DESATIVOU O CADASTRO' + NL + linha[2] + ' (' + linha[1] + ')' + NL + linha[0] + NL + 'Comissões pendentes e futuras deixam de ser pagas.';
  } else if (acao === 'af_reativar') {
    linha[5] = 'ativo'; linha[13] = ''; linha[7] = dataSP(agora);
    grava(linha);
    out.resposta = { ok: true, dados: dados(linha) };
    out.telegram = '🔁 AFILIADO REATIVADO' + NL + linha[2] + ' (' + linha[1] + ')' + NL + linha[0];
  } else {
    // resultados: Comissoes 0 payment_id 1 lote 2 ref 7 comissao ; Lotes 1 ref 8 valor 9 status
    const ref = txt(linha[1]);
    let vendas = 0, ganhos = 0, pago = 0;
    for (const c of comissoes) { if (txt(c[2]) === ref) { vendas++; ganhos += num(c[7]); } }
    for (const l of lotes) { if (txt(l[1]) === ref && txt(l[9]) === 'paga') { pago += num(l[8]); } }
    out.resposta = { ok: true, vendas: vendas, ganhos: reais(ganhos), pago: reais(pago), receber: reais(Math.max(0, ganhos - pago)) };
  }
} else {
  out.resposta = { ok: false, motivo: 'acao' };
}

// formatos prontos para o Make
out.resposta_json = JSON.stringify(out.resposta);
out.tem_escrita = out.escrita ? out.escrita.metodo : 'nao';
out.escrita_range = out.escrita ? out.escrita.range : '';
out.escrita_corpo = out.escrita ? JSON.stringify({ values: out.escrita.values }) : '';
out.tem_email = out.email ? 'sim' : 'nao';
out.tem_telegram = out.telegram ? 'sim' : 'nao';
return [{ json: out }];
